#!/bin/bash
# usage: gates.sh <tag> <gate ...>   gates: a3d dressup lib golden fm1 cli mcp viz clippy other
cd /home/ricky/personal_repos/rs_cam || exit 1
S=/tmp/claude-1001/-home-ricky-personal-repos-rs-cam/ce846d39-41d4-4e44-be56-d5dd5295a423/scratchpad/p42
tag=$1; shift
A3D="a_derived_rest_rough_cuts_only_the_leftovers_d44 a_geodesic_arc_end_reads_the_stock_p22f2 a_geodesic_cap_survives_every_dressup_s7_4 a_geodesic_layer_opens_with_a_helix_bore_p22b a_geodesic_slice_cuts_no_full_slot_sweep_p22f a_geodesic_step_over_the_ceiling_is_cut_capped_d65 a_ramp_entry_keeps_to_its_planned_footprint_p39 a_rest_consumer_starts_at_the_left_stock_top_d50 a_rest_consumer_stays_inside_the_source_boundary_d48 a_rest_entry_does_not_peck_through_cleared_air_d55 a_rest_op_holds_one_depth_at_the_band_c4 a_rough_plans_its_cut_and_link_descents_to_the_core_limit_k5_centrecut a_rough_publishes_the_regions_it_leaves_d44 adaptive3d_boundary_clear_parity adaptive3d_boundary_clip_leaves_no_phantom_stock_g_boundaryphantom adaptive3d_by_area_cells_confine_jobs adaptive3d_by_area_matches_global_stock adaptive3d_commanded_ladder adaptive3d_emission_byte_parity adaptive3d_entry_coalescing_f038 adaptive3d_entry_stock_aware adaptive3d_global_gate_drapes_below_floor adaptive3d_interior_cell_parity_f029 adaptive3d_keep_down_link_f038b adaptive3d_lift_bridge_b1 adaptive3d_plan_matches_merged_path_g_plansimgap adaptive3d_planner_never_ahead_of_emitted_path adaptive3d_planner_stock_xy_f027 adaptive3d_plans_every_slice_piece_g_adapt3dpieces adaptive3d_post_tsp_z_monotonicity adaptive3d_subtool_channel_gouge adaptive3d_wanaka_rough6_no_phantom_rapid_g_phantomstamp agent_search_coverage by_area_walls_cut_each_region_level_c4b contour_each_level_is_off_by_default_c4 geodesic_adaptive_holds_the_pass_load_c12 geodesic_adaptive_keeps_the_research_geometry_s7_4"
DRESS="capability_link_moves_safety dressup_span_invariants tabs_sit_on_straight_sides_p5 tabs_bridge_width_and_height_p5b the_tab_layout_is_the_cut_layout_p4_6 constrained_max_modulation_f039 entry_moves_stock_aware_g_rampterrain finishing_defaults_have_no_ramp_entry_r10 the_modulator_keeps_the_lifted_feed_p11b2 lead_in_out_feed_rates_f040 plunge_guard_p3 a_feed_cap_binds_every_feed_stage_c38 an_entry_ramp_follows_the_arc_g_rampchord a_peck_ladder_is_never_split_into_a_rapid_into_stock_g_pecksplit fed_chords_ride_the_surface_g_tierburial a_finished_edge_keeps_its_corner_p6_0b a_lead_curls_away_from_the_part_p6_0c feed_modulation_has_three_modes_p32 a_drill_rapid_stays_over_the_standing_stock_p36"
OTHER="one_record_on_every_surface_p29_10 the_depth_that_cut_is_a_measured_load_g_s3depth no_removing_sample_is_outside_the_gates_p29_6 every_limit_is_a_limit_id_p29_2 a_weak_bound_cannot_refuse_an_export_g_s4weak finish_depth_is_reported_not_capped_fm6 a_criterion_carries_its_own_bound_g_s4bound histogram_population_is_the_gate_population_g_cuthist a_rest_op_slower_than_fresh_is_told_r3 findings_transport_join_h21 a_job_with_each_finding_exports_and_names_it_k6 a_rough_island_above_the_stock_to_leave_is_flagged_g_roughcov the_volumetric_wrapper_keeps_its_produced_w6_5 every_op_states_its_capabilities_w2_4 region_cap_honesty_f3 gate_population_vacuity_xvac depth_beyond_stock_core_g_depthstockcore every_consumer_reads_one_claimed_band_g1 narrate_regions_closed_c8 folder_maps_name_real_files_f140"
tests() { local out=""; for t in $1; do [ -f crates/rs_cam_core/tests/$t.rs ] && out="$out --test $t"; done; echo $out; }
for g in "$@"; do
  log=$S/gate_${tag}_$g.log
  case $g in
    a3d) timeout 5400 scripts/cargo_lane.sh test -p rs_cam_core -q --features test-support,heavy-tests --no-fail-fast $(tests "$A3D") -j 2 > $log 2>&1 ;;
    dressup) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_core -q --features test-support,heavy-tests --no-fail-fast $(tests "$DRESS") -j 2 > $log 2>&1 ;;
    other) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_core -q --features test-support,heavy-tests --no-fail-fast $(tests "$OTHER") -j 2 > $log 2>&1 ;;
    lib) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_core -q --lib --no-fail-fast -j 2 > $log 2>&1 ;;
    golden) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_core -q --features test-support,heavy-tests --test every_op_keeps_its_toolpath_g_opgolden -j 2 > $log 2>&1 ;;
    fm1) timeout 5400 scripts/cargo_lane.sh test -p rs_cam_core -q --features heavy-tests --test feeds_matrix_instrument_fm1 -j 2 > $log 2>&1 ;;
    cli) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_cli -q --no-fail-fast -j 2 > $log 2>&1 ;;
    mcp) timeout 3600 scripts/cargo_lane.sh test -p rs_cam_mcp -q --no-fail-fast -j 2 > $log 2>&1 ;;
    viz) if [ -z "$(pgrep -ax rs_cam_gui)" ]; then timeout 3600 scripts/cargo_lane.sh test -p rs_cam_viz -q --lib -j 2 -- --test-threads 2 > $log 2>&1; else echo "GUI runs: viz not run" > $log; fi ;;
    clippy) timeout 5400 scripts/cargo_lane.sh clippy --workspace --all-targets --features rs_cam_core/heavy-tests,rs_cam_core/research,rs_cam_core/test-support -j 2 -- -D warnings > $log 2>&1 ;;
  esac
  echo "== $g rc=$? : $(grep -c '^test result: ok' $log) ok binaries, $(grep -c '^test result: FAILED' $log) failed binaries"
  grep -E "^test result|^test .* FAILED|^error|^---- " $log | grep -v "^test result: ok. 0 passed" | head -40
done
